  ('749ff54f-a7b5-5d06-a2e4-af2ea872b313', 'en:hypoglycemia:noun', 'hypoglycemia', 'hypoglycemia', '/ˌhaɪpoʊɡlaɪˈsiːmiə/', 'noun'),
  ('c7f8a585-1cae-5d3e-935c-d31c0180ff69', 'en:hypertension:noun', 'hypertension', 'hypertension', '/ˌhaɪpərˈtenʃən/', 'noun'),
