  ('49d5dafd-e5ef-5910-a499-ac43532bc27a', 'en:osteoporosis:noun', 'osteoporosis', 'osteoporosis', '/ˌɑːstioʊpəˈroʊsɪs/', 'noun'),
  ('8d0aa50d-41bc-50c8-9e18-d9b4d6029252', 'en:hematoma:noun', 'hematoma', 'hematoma', '/ˌhiːməˈtoʊmə/', 'noun'),
  ('00e5e75f-2fc9-5187-a072-346f7a7c5798', 'en:hemorrhage:noun', 'hemorrhage', 'hemorrhage', '/ˈhemərɪdʒ/', 'noun'),
  ('b3f60ee8-87df-531a-89d0-5e0d680d4129', 'en:intravenous:adjective', 'intravenous', 'intravenous', '/ˌɪntrəˈviːnəs/', 'adjective'),
  ('4c93b7a0-bcc4-5015-b843-0c254f1c01f8', 'en:subcutaneous:adjective', 'subcutaneous', 'subcutaneous', '/ˌsʌbkjuˈteɪniəs/', 'adjective'),
