  ('066353b9-6706-5e20-9395-c6e078fc732e', 'en:carcinoma:noun', 'carcinoma', 'carcinoma', '/ˌkɑːrsɪˈnoʊmə/', 'noun'),
  ('49b5a3eb-6f11-59ee-9aaf-0ab372c4d0d5', 'en:metastasis:noun', 'metastasis', 'metastasis', '/məˈtæstəsɪs/', 'noun'),
  ('7030244e-1c99-5a2b-9cad-2d78d14e0a2f', 'en:biopsy:noun', 'biopsy', 'biopsy', '/ˈbaɪɑːpsi/', 'noun'),
