insert into public.word_senses (id, stable_key, word_id, module_id, category_id, meaning_en, meaning_zh, usage_note)
values
  ('358e5837-55bc-5f39-adb8-7caf7bb6e34b', 'medical_english:anatomy:abdomen:noun', 'f63b9929-7121-5463-a14e-dcdc679d0720', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'f2f95a33-ad8a-576c-9ec4-563e8ad57801', 'the part of the trunk between the chest and the pelvis', '腹部', '写查体或主诉部位时用。胸是 chest，盆腔是 pelvis，不要把上腹痛写成胸口痛。'),
  ('19d42134-4ada-5175-82ba-34bbf07f4492', 'medical_english:anatomy:airway:noun', 'da71ddd8-b2e4-581d-bf25-734005a1ecec', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'f2f95a33-ad8a-576c-9ec4-563e8ad57801', 'the passage that carries air from the mouth or nose into the lungs', '气道；呼吸道', '强调空气进出肺的通路是否通畅。喘气本身先写 dyspnea，只有通路受阻或要保护通气时才写 airway。'),
  ('333d4b9b-7ddd-5e04-a472-d5cc91dba2ee', 'medical_english:physiology:hypoxia:noun', 'b57675fa-31ed-5ed9-b0b4-bed2dbbc7405', '52d53e9d-b343-50d9-b0d8-059b2540f890', '0419c1eb-5b7b-5fdc-aacb-c4daf1afd345', 'a shortage of oxygen in the tissues', '缺氧', '组织缺氧才能写。血氧读数低常先写 hypoxemia；没有氧供或灌注证据时，不要随口升级成 hypoxia。'),
  ('86f0a711-5a3d-507c-a10d-d6f7b037338e', 'medical_english:physiology:pulse:noun', '2725590e-0062-5b96-87e4-9f314ef37624', '52d53e9d-b343-50d9-b0d8-059b2540f890', '0419c1eb-5b7b-5fdc-aacb-c4daf1afd345', 'the heartbeat felt in an artery, used as a vital-sign count', '脉搏', '查体摸到的动脉搏动或生命体征里的脉率。心电图上的心率可以不同，不要把摸不到的电活动直接写成 pulse。'),
  ('1f51fe64-c8d1-5dd6-950f-fc1978eb0009', 'medical_english:pathology:infection:noun', '85bc433b-292c-55b0-9ae6-bb0f20b71d55', '52d53e9d-b343-50d9-b0d8-059b2540f890', '3f8e08d5-d603-52c6-a794-038712ff8d03', 'invasion and multiplication of a pathogen that injures the host', '感染', '有病原体侵入并造成损害才写。单纯发热或定植还不到 infection；脓毒症是更重的全身反应。'),
  ('3252cbff-db84-5c22-9f32-df94e98cb774', 'medical_english:symptoms:fever:noun', '28c3fb66-92bf-53d7-9067-48722602ff0f', '52d53e9d-b343-50d9-b0d8-059b2540f890', '58a9e7bc-4a47-5465-bf8e-a6312ab0df40', 'an abnormally high body temperature as a symptom of illness', '发热；发烧', '体温高于正常才能写。患者只说怕冷或出汗还不够；具体数字更清楚时写出温度。'),
  ('34321505-f464-5e60-8ed9-1e3eebc56225', 'medical_english:diagnosis:rule-out:phrasal-verb', 'dd85064e-57ba-538f-a996-9272f47d202f', '52d53e9d-b343-50d9-b0d8-059b2540f890', '418fd2cc-1b52-52cd-a6b1-460558fc0fad', 'to exclude a diagnosis after enough testing or clinical reasoning', '排除（某一诊断）', '检查或推理已经足够否定该病才写。还在怀疑时写 consider 或 cannot exclude，不要提前 rule out。'),
  ('610cc9c0-34fe-5cdb-80fd-a034fe30d4a8', 'medical_english:laboratory:culture:noun', '64e7c7d2-f99f-5f09-980b-34c2b6cccca1', '52d53e9d-b343-50d9-b0d8-059b2540f890', '10e2306a-068b-5b0d-be9c-deb0606e5aae', 'a laboratory test that tries to grow organisms from a specimen', '培养（微生物学检验）', '标本拿去培养病原体时用。普通血常规不是 culture；培养阴性也不等于没有感染。'),
  ('899f5e47-5609-5bb9-accd-7eac3f2ccf8b', 'medical_english:laboratory:elevated:adjective', '76c87523-0ea5-5cb7-a07f-ae33823faccb', '52d53e9d-b343-50d9-b0d8-059b2540f890', '10e2306a-068b-5b0d-be9c-deb0606e5aae', 'higher than the reference range for a laboratory value', '升高的；高于参考范围的', '化验值高于参考范围时用。还在正常高限内不要写；具体数字比单独一个 elevated 更清楚。'),
  ('4ae522fe-c75e-50fd-a033-a40d3c3ba835', 'medical_english:pharmacology:dose:noun', '025e4957-d123-5d6f-9a48-d09501e7fb1a', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'be176af9-cee2-5fc3-a8c1-dabaf200bb70', 'the measured amount of a drug given at one time or over a course', '剂量', '一次或一个疗程给多少药。给药途径是 route，服药次数是 frequency，不要互相替代。'),
  ('f035aa3f-5170-532a-887f-1802ed0a8990', 'medical_english:pharmacology:allergy:noun', 'e11e87c9-d744-5dfd-8f94-0184a64a52be', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'be176af9-cee2-5fc3-a8c1-dabaf200bb70', 'an immune reaction to a drug or other substance, often with rash or worse', '过敏', '真正的免疫反应才写 allergy。普通副作用或胃肠不适先写 intolerance，不要把所有“不能吃”都写成过敏。'),
  ('6572c533-12be-588b-924d-b4a09af881d3', 'medical_english:pharmacology:side-effect:noun', '00597f2c-17fc-59b0-a890-79d9aeb3a807', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'be176af9-cee2-5fc3-a8c1-dabaf200bb70', 'an unwanted effect of a drug besides the intended treatment effect', '副作用', '药物带来的额外不良反应。过敏是免疫反应，治疗失败不是 side effect。'),
  ('86436f51-46d6-5bd6-a843-27e90db56d22', 'medical_english:surgery_procedures:incision:noun', 'afd6a3e2-6c2a-5d3c-b26d-43cbd4a74ae8', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'fa342f3d-0091-5406-a280-66eb64166d92', 'a surgical cut through skin or other tissue', '切口', '刀切开的口子。伤口感染或裂开要另写；单纯缝线不是 incision。'),
  ('7b1b0d39-7f5f-5c82-8a53-bb219eaf43de', 'medical_english:surgery_procedures:procedure:noun', '737cad80-4443-554c-bf6f-a3892e3edcd1', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'fa342f3d-0091-5406-a280-66eb64166d92', 'a planned diagnostic or therapeutic intervention, often invasive', '操作；手术或有创检查', '有计划的诊疗操作。吃药或普通查体不要写成 procedure；具体手术名更清楚时优先写手术名。'),
  ('54ddeb3d-a1a8-5409-875e-b41d4d1da227', 'medical_english:surgery_procedures:suture:noun', 'b76d3d78-4104-5f57-bca4-ddc9b9ff2e53', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'fa342f3d-0091-5406-a280-66eb64166d92', 'stitches used to close a wound or surgical cut', '缝线；缝合', '用来对合伤口的线。皮肤钉是 staples；拆线写 remove sutures，不要写成切开。'),
  ('408498f0-c9c4-5804-8665-8b8b12db7098', 'medical_english:treatment:discharge:verb', '8e8fd01e-0998-5a19-8efa-545cd0a856f9', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'd1c91e1b-3970-5d28-9e17-446cc90b1388', 'to formally release a patient from hospital or clinic care', '出院；让患者离开医疗机构', '正式结束本次住院或就诊。伤口渗液那个 discharge 是另一义；转科或请假回家还不是 discharged。'),
  ('baf8515f-f4c7-5785-abbf-5e4e60594f87', 'medical_english:morphology:endocarditis:noun', '1a9982a1-c142-5445-9ce0-0ac95f887791', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'inflammation of the inner lining of the heart (endo- inner + cardi- heart + -itis inflammation)', '心内膜炎', 'endo- 是里面，cardi- 是心，-itis 是炎症，合起来是心内膜炎症。词根能猜出部位和炎症，但不能只靠构词当瓣膜感染诊断。'),
  ('9fd15125-b658-5a4d-9001-c1f78d8a9c90', 'medical_english:morphology:dermatitis:noun', 'b194033a-5ee5-5bef-8276-e34d72886398', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'inflammation of the skin (derm- skin + -itis inflammation)', '皮炎', 'derm- 是皮肤，-itis 是炎症。看到红痒皮疹可以先猜皮炎，但接触性、特应性还是感染要另找证据，不能只靠词根定类型。'),
  ('bad4ee06-bc67-59f3-b201-b54488f88616', 'medical_english:morphology:hepatitis:noun', 'feccf993-7119-58d7-b4fd-96a160193e15', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'inflammation of the liver (hepat- liver + -itis inflammation)', '肝炎', 'hepat- 是肝，-itis 是炎症。转氨酶升高只能提示肝损伤，病毒、酒精还是药物要另查，不能把词根猜成确定病因。'),
  ('ef08d384-9dea-5dc4-bc09-b306daa4ead1', 'medical_english:morphology:gastritis:noun', '6fc69564-221d-5a2d-8398-06ae19946298', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'inflammation of the stomach lining (gastr- stomach + -itis inflammation)', '胃炎', 'gastr- 是胃，-itis 是炎症。上腹痛可先猜胃黏膜炎症，但溃疡、反流或心源性疼痛不能只靠构词排除。'),
  ('0f69a679-de9b-5e73-a2c7-ca13209e4603', 'medical_english:morphology:arthritis:noun', 'd95c818f-c5bc-5ca3-8bb5-1af1f5c65a73', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'inflammation of a joint (arthr- joint + -itis inflammation)', '关节炎', 'arthr- 是关节，-itis 是炎症。关节肿痛可先按构词理解，但骨关节炎、痛风或感染要靠检查，不能只靠 -itis 当同一病。'),
  ('f40f9764-b069-5ff3-bf64-4da82e5f22db', 'medical_english:morphology:leukemia:noun', 'b83800cd-209d-52ca-b9eb-60752c220f8a', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a cancer of white blood cells (leuko- white + -emia blood condition)', '白血病', 'leuko- 是白，-emia 是血里的状态，字面是白细胞相关的血液病。词根能提醒查血，但不能把任何白细胞升高猜成 leukemia。'),
  ('00b9b585-bb9a-5859-be85-8a8e53a2d6d8', 'medical_english:morphology:anemia:noun', '6c9bf2a6-b6bc-5f3b-aa1f-3308b259e026', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a low red-cell or hemoglobin level in the blood (an- without + -emia blood)', '贫血', 'an- 是缺乏，-emia 是血液状态，合起来是血里缺少红细胞或血红蛋白。脸色差只能提示，确诊要看化验，不能只靠词根。'),
  ('6aaf515e-ba87-5d97-a171-9311971640f7', 'medical_english:morphology:hyperglycemia:noun', '6bdf4ef1-a000-5260-a176-b3e623573d7d', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'an abnormally high blood glucose (hyper- high + glyc- sugar + -emia blood)', '高血糖', 'hyper- 是过高，glyc- 是糖，-emia 在血里。词根能读出“血里糖高”，但一次餐后升高不能只靠构词当成糖尿病诊断。'),
  ('ac27ae1e-4cb6-52f3-aab7-90b426bdc12f', 'medical_english:morphology:hypoglycemia:noun', '749ff54f-a7b5-5d06-a2e4-af2ea872b313', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'an abnormally low blood glucose (hypo- low + glyc- sugar + -emia blood)', '低血糖', 'hypo- 是过低，glyc- 是糖，-emia 在血里。出汗心慌可先猜血糖低，但必须测血糖，不能只靠构词当发作。'),
  ('0644f027-a925-5f06-8802-e999b066e300', 'medical_english:morphology:hypertension:noun', 'c7f8a585-1cae-5d3e-935c-d31c0180ff69', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'persistently high blood pressure (hyper- high + tens- pressure + -ion state)', '高血压', 'hyper- 是过高，tens- 是压力。一次诊室血压高还不够，要看是否持续升高，不能把词根猜成已经确诊。'),
  ('f63a763c-82d6-5d6e-93ec-b05f4f232e54', 'medical_english:morphology:hypotension:noun', 'ec03e166-d876-511b-840e-fca706a35d50', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'abnormally low blood pressure (hypo- low + tens- pressure + -ion state)', '低血压', 'hypo- 是过低，tens- 是压力。头晕不等于低血压；要有血压数字，也不能只靠构词判断休克。'),
  ('9938ac2c-db4f-59f9-8fd2-1b29d7815b49', 'medical_english:morphology:tachycardia:noun', '8b111d16-58a9-5b08-8d99-f413763a65f8', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'an abnormally fast heart rate (tachy- fast + cardi- heart + -ia condition)', '心动过速', 'tachy- 是快，cardi- 是心。词根能读出心率快，但窦性、房颤还是室速要看心电图，不能只靠构词。'),
  ('6168fa0d-0b47-5cf7-8099-adc6c5a01da6', 'medical_english:morphology:bradycardia:noun', 'ecfc9fea-2662-57a8-a06b-e23459ca8024', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'an abnormally slow heart rate (brady- slow + cardi- heart + -ia condition)', '心动过缓', 'brady- 是慢，cardi- 是心。词根能读出心率慢，但运动员静息心率慢不一定是病，不能只靠构词当传导阻滞。'),
  ('d579e8ca-db94-5e11-aa4e-b9aca4bb9bc0', 'medical_english:morphology:neuropathy:noun', '35089c6b-84fc-5863-8ccc-ad49140d3e10', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'disease or dysfunction of peripheral nerves (neuro- nerve + -pathy disease)', '神经病；周围神经病变', 'neuro- 是神经，-pathy 是病变。手脚麻木可先猜神经出问题，但是脑卒中还是神经根病要另辨，不能只靠词根。'),
  ('857a7a18-c3cb-58b9-935b-784bf25279f7', 'medical_english:morphology:myopathy:noun', '6a6a7280-19c0-579c-bd0f-9e353d5c1f66', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'disease of muscle tissue (myo- muscle + -pathy disease)', '肌病', 'myo- 是肌肉，-pathy 是病变。词根能提示肌肉本身有病，但无力也可能来自神经，不能只靠构词。'),
  ('b7506dc2-0b92-5a0f-bbba-6d2a937e2fea', 'medical_english:morphology:osteoporosis:noun', '49d5dafd-e5ef-5910-a499-ac43532bc27a', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'porous, low-density bone that fractures easily (osteo- bone + -porosis porous condition)', '骨质疏松', 'osteo- 是骨，-porosis 是变得疏松。词根能读出骨头变空，但确诊看骨密度，一次背痛不能只靠构词下诊断。'),
  ('52622478-30c2-5753-bbee-2b74a6a91c46', 'medical_english:morphology:hematoma:noun', '8d0aa50d-41bc-50c8-9e18-d9b4d6029252', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a localized collection of blood outside vessels (hemat- blood + -oma mass)', '血肿', 'hemat- 是血，-oma 是一团。词根是“血凝成块”，不是肿瘤。皮肤青紫可以只是瘀斑，不能只靠构词写成血肿。'),
  ('76fd5eb3-dfb4-5875-a98d-fa374c7560fa', 'medical_english:morphology:hemorrhage:noun', '00e5e75f-2fc9-5187-a072-346f7a7c5798', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'active bleeding, especially a clinically important loss of blood (hemat-/hem- blood + -rrhage bursting forth)', '出血', 'hem- 是血，-rrhage 是涌出。词根强调血涌出来。少量渗血先写 bleeding，不能只靠构词升级成大出血。'),
  ('5d4b1501-1a63-5847-be95-a0029e9d7f14', 'medical_english:morphology:intravenous:adjective', 'b3f60ee8-87df-531a-89d0-5e0d680d4129', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'given or located inside a vein (intra- within + ven- vein + -ous relating to)', '静脉内的', 'intra- 是里面，ven- 是静脉。词根能读出给药途径，但写错成皮下或肌肉时，不能只靠构词补救，必须看实际路径。'),
  ('f70995bc-2cd0-53d7-be5c-6c90c96fff52', 'medical_english:morphology:subcutaneous:adjective', '4c93b7a0-bcc4-5015-b843-0c254f1c01f8', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'beneath the skin (sub- under + cutane- skin + -ous relating to)', '皮下的', 'sub- 是下面，cutane- 是皮肤。词根只说明层次在皮下。胰岛素常见此路径，但不能只靠构词和皮内或肌肉注射混用。'),
  ('11a61f0f-768e-5867-8b03-934390af2c3f', 'medical_english:morphology:neoplasm:noun', '39f71d9a-5e82-5cb8-9394-6dbfeccebdb3', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a new abnormal growth of tissue; a tumor (neo- new + -plasm formed substance)', '肿瘤；赘生物', 'neo- 是新的，-plasm 是形成的组织。词根是“新长出来的东西”，良性恶性都可能，不能只靠构词写成癌。'),
  ('ed4669d1-326a-5d36-b420-40eccbe82e50', 'medical_english:morphology:carcinoma:noun', '066353b9-6706-5e20-9395-c6e078fc732e', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a malignant tumor of epithelial cells (carcino- cancer + -oma mass)', '癌；上皮来源的恶性肿瘤', 'carcino- 指向癌，-oma 是肿块。词根比 neoplasm 更像恶性肿瘤，但肉瘤或淋巴瘤不是 carcinoma，不能只靠 -oma 猜癌。'),
  ('f0dd024b-6c1a-5391-a8db-813b1376450e', 'medical_english:morphology:metastasis:noun', '49b5a3eb-6f11-59ee-9aaf-0ab372c4d0d5', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'spread of cancer to a distant site (meta- beyond + -stasis standing/placement)', '转移', 'meta- 是超越原位，-stasis 是停留在别处。词根能读出“跑到远处”。局部侵犯还不是转移，不能只靠构词。'),
  ('517b0224-26f1-53b7-862b-3a3069b8f96a', 'medical_english:morphology:biopsy:noun', '7030244e-1c99-5a2b-9cad-2d78d14e0a2f', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'removal of tissue for diagnosis (bio- life/tissue + -opsy examination)', '活检；活组织检查', 'bio- 是活组织，-opsy 是查看。词根是取一块组织来看。切除整个病灶是 excision，不能只靠构词和细胞学混用。'),
  ('9dcd9f90-cfd5-5a7d-959d-d23f833457c9', 'medical_english:morphology:prognosis:noun', '373f8047-3e64-50f0-9b03-ea6ee8f1ece0', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the likely course and outcome of a disease (pro- before + -gnosis knowledge)', '预后', 'pro- 是事先，-gnosis 是认知，词根是提前判断病情走向。诊断是现在是什么病，不能只靠构词把预后写成诊断。'),
  ('413dc419-b817-588e-8de9-16a356316714', 'medical_english:morphology:diagnosis:noun', 'a49a9100-72ec-5bfb-84f5-7ebc4ff91008', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the identification of a disease (dia- through/apart + -gnosis knowledge)', '诊断', 'dia- 是穿过、分辨，-gnosis 是认知：把表现分辨成病名。词根能提醒“认出是什么”，但工作诊断和确诊强度不同，不能只靠构词。'),
  ('7ce6fedc-390d-5301-b89d-8ee697729495', 'medical_english:morphology:antibiotic:noun', 'c3e08d12-0a49-570f-ab4b-efa601a9322a', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a drug used against living microbes (anti- against + bio- life + -tic relating to)', '抗生素', 'anti- 是对抗，bio- 是生命（此处指微生物）。词根是“对抗活的病原”。抗病毒药不是 antibiotic，不能只靠构词。'),
  ('17f49a67-5f61-5573-908e-c9b05cc02e7c', 'medical_english:morphology:antipyretic:noun', '6531a574-b93f-5e9c-9b3c-992318f7cd66', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a medicine that lowers fever (anti- against + pyr- fire/fever + -etic relating to)', '退热药', 'anti- 是对抗，pyr- 是热。词根是退热，不是杀菌。发热原因仍要查，不能只靠构词把退热药当成抗生素。')
insert into public.contexts (id, stable_key, word_sense_id, context_sentence, target_text, plain_english_paraphrase, sentence_translation_zh, collocations, context_genre, source_type, source_title, source_url, doi, pmid)
values
  ('95d49150-8d3e-570c-90f1-65931def5f65', 'medical_english:anatomy:abdomen:noun:med-anatomy-abdomen-001', '358e5837-55bc-5f39-adb8-7caf7bb6e34b', 'The patient reported dull pain in the lower abdomen after meals.', 'abdomen', 'After eating, the patient felt a dull ache in the lower belly.', '患者诉餐后下腹部钝痛。', array['lower abdomen', 'abdomen was soft', 'pain in the abdomen']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('a80e63f9-1830-5b83-b64a-e7717598b645', 'medical_english:anatomy:airway:noun:med-anatomy-airway-001', '19d42134-4ada-5175-82ba-34bbf07f4492', 'The nurse kept the airway open while the patient was still drowsy.', 'airway', 'The nurse made sure air could still move in and out while the patient was sleepy.', '患者仍嗜睡时，护士保持气道通畅。', array['keep the airway open', 'airway obstruction', 'secure the airway']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('27a95145-474b-5edc-a543-49671d42f04f', 'medical_english:physiology:hypoxia:noun:med-physiology-hypoxia-001', '333d4b9b-7ddd-5e04-a472-d5cc91dba2ee', 'Supplemental oxygen was started after signs of hypoxia appeared during walking.', 'hypoxia', 'Extra oxygen was given when the patient started to look short of oxygen while walking.', '步行时出现缺氧征象后开始给氧。', array['signs of hypoxia', 'tissue hypoxia', 'correct hypoxia']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('82ede408-0b70-5798-bdf3-f506954caade', 'medical_english:physiology:pulse:noun:med-physiology-pulse-001', '86f0a711-5a3d-507c-a10d-d6f7b037338e', 'Her pulse was regular at 88 beats per minute.', 'pulse', 'The beating felt at the wrist came at a steady 88 times each minute.', '脉搏规则，每分钟 88 次。', array['radial pulse', 'pulse rate', 'regular pulse']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('ba1520e2-36e6-58d7-940d-c2015fb2ac8f', 'medical_english:pathology:infection:noun:med-pathology-infection-001', '1f51fe64-c8d1-5dd6-950f-fc1978eb0009', 'Wound infection was suspected when redness and pus appeared on day three.', 'infection', 'Doctors thought germs had entered the wound after it turned red and started to drain pus.', '第三日伤口出现红肿和脓液，怀疑伤口感染。', array['wound infection', 'bacterial infection', 'treat the infection']::text[], 'case_report', 'original_example', null, null, null, null),
  ('829a28c4-98c5-5a03-9642-24c110136304', 'medical_english:symptoms:fever:noun:med-symptoms-fever-001', '3252cbff-db84-5c22-9f32-df94e98cb774', 'She presented with fever and a dry cough for two days.', 'fever', 'She came in after two days of a high temperature and a dry cough.', '她因发热伴干咳两天就诊。', array['high fever', 'fever and chills', 'fever of unknown origin']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('1201d464-17cb-5b93-aa28-c4a1a6a08f85', 'medical_english:diagnosis:rule-out:phrasal-verb:med-diagnosis-rule-out-001', '34321505-f464-5e60-8ed9-1e3eebc56225', 'A chest radiograph was obtained to rule out pneumonia.', 'rule out', 'A chest X-ray was taken so doctors could see whether pneumonia could be excluded.', '完善胸片以排除肺炎。', array['rule out pneumonia', 'rule out fracture', 'cannot yet rule out']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('ecf03213-cd27-5491-ae69-a98bfac1305f', 'medical_english:laboratory:culture:noun:med-laboratory-culture-001', '610cc9c0-34fe-5cdb-80fd-a034fe30d4a8', 'Blood culture was drawn before the first dose of antibiotics.', 'culture', 'A blood sample was taken to grow any germs before antibiotics were started.', '在首剂抗生素之前抽取了血培养。', array['blood culture', 'urine culture', 'culture grew']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('ddad9859-5714-53ad-a0e5-bfc53d233418', 'medical_english:laboratory:elevated:adjective:med-laboratory-elevated-001', '899f5e47-5609-5bb9-accd-7eac3f2ccf8b', 'The white-cell count was elevated at 14.2 × 10⁹ per liter.', 'elevated', 'The white blood cell number was above the usual laboratory range.', '白细胞计数升高，为 14.2 × 10⁹/L。', array['elevated white-cell count', 'elevated creatinine', 'mildly elevated']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('d8af6ada-b7a7-5781-87be-181a594bd7e2', 'medical_english:pharmacology:dose:noun:med-pharmacology-dose-001', '4ae522fe-c75e-50fd-a033-a40d3c3ba835', 'The evening dose of acetaminophen was held because of rising liver enzymes.', 'dose', 'The night-time amount of acetaminophen was skipped after liver tests went up.', '因肝酶上升，当晚那次对乙酰氨基酚剂量暂停。', array['daily dose', 'hold a dose', 'low dose']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('07a65aaf-d1ab-50bf-b796-99b850799519', 'medical_english:pharmacology:allergy:noun:med-pharmacology-allergy-001', 'f035aa3f-5170-532a-887f-1802ed0a8990', 'The admission note listed a penicillin allergy with rash.', 'allergy', 'The chart said penicillin had caused a rash in the past.', '入院记录注明青霉素过敏，表现为皮疹。', array['drug allergy', 'penicillin allergy', 'no known drug allergies']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('271de9b3-45da-59ae-b932-87a93f76e653', 'medical_english:pharmacology:side-effect:noun:med-pharmacology-side-effect-001', '6572c533-12be-588b-924d-b4a09af881d3', 'Nausea is a common side effect of this oral antibiotic.', 'side effect', 'Feeling sick to the stomach often happens with this antibiotic even when it is working.', '恶心是这种口服抗生素的常见副作用。', array['common side effect', 'side effect of therapy', 'report a side effect']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('2426f37b-7bc8-574a-b402-7975a51a8065', 'medical_english:surgery_procedures:incision:noun:med-surgery-incision-001', '86436f51-46d6-5bd6-a843-27e90db56d22', 'The abdominal incision was clean, dry, and without drainage.', 'incision', 'The surgical cut on the abdomen looked clean and was not leaking fluid.', '腹部切口清洁干燥，无渗液。', array['surgical incision', 'midline incision', 'incision was clean']::text[], 'operative_note', 'original_example', null, null, null, null),
  ('6eb74fe4-146b-5da4-81bb-4f09bab14a66', 'medical_english:surgery_procedures:procedure:noun:med-surgery-procedure-001', '7b1b0d39-7f5f-5c82-8a53-bb219eaf43de', 'The procedure was explained, and written consent was obtained.', 'procedure', 'Staff described the planned intervention and the patient signed a consent form.', '已说明该操作并取得书面知情同意。', array['planned procedure', 'bedside procedure', 'after the procedure']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('c1994f8a-4b4a-544e-b4fd-e7e42951d880', 'medical_english:surgery_procedures:suture:noun:med-surgery-suture-001', '54ddeb3d-a1a8-5409-875e-b41d4d1da227', 'Skin sutures were removed on postoperative day ten.', 'sutures', 'The stitches in the skin were taken out ten days after surgery.', '术后第 10 日拆除皮肤缝线。', array['skin sutures', 'remove sutures', 'absorbable sutures']::text[], 'operative_note', 'original_example', null, null, null, null),
  ('ed067ec5-8370-5c7e-884b-b9d178dd899f', 'medical_english:treatment:discharge:verb:med-treatment-discharge-001', '408498f0-c9c4-5804-8665-8b8b12db7098', 'He was discharged home with oral antibiotics and a wound check in two days.', 'discharged', 'He was allowed to leave the hospital with antibiotic pills and a planned wound visit.', '他带口服抗生素出院回家，并约定两日后伤口复查。', array['discharged home', 'discharge planning', 'fit for discharge']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('3a75b33c-0dc3-5a0a-8aef-9555b982322f', 'medical_english:morphology:endocarditis:noun:med-morphology-endocarditis-001', 'baf8515f-f4c7-5785-abbf-5e4e60594f87', 'Fever and a new murmur raised concern for bacterial endocarditis.', 'endocarditis', 'A fever plus a newly heard heart sound made doctors worry the inner heart lining was infected.', '发热和新出现的杂音使医生担心细菌性心内膜炎。', array['infective endocarditis', 'bacterial endocarditis', 'valve endocarditis']::text[], 'case_report', 'original_example', null, null, null, null),
  ('deda40a8-dd09-5e53-a577-645a4c48634d', 'medical_english:morphology:dermatitis:noun:med-morphology-dermatitis-001', '9fd15125-b658-5a4d-9001-c1f78d8a9c90', 'Contact dermatitis developed under the adhesive dressing.', 'dermatitis', 'The skin under the sticky dressing became inflamed.', '敷料粘贴处出现接触性皮炎。', array['contact dermatitis', 'atopic dermatitis', 'severe dermatitis']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('79e5335d-ccea-5e9c-b3f5-d03902e151e4', 'medical_english:morphology:hepatitis:noun:med-morphology-hepatitis-001', 'bad4ee06-bc67-59f3-b201-b54488f88616', 'Acute hepatitis can present with jaundice, dark urine, and fatigue.', 'hepatitis', 'Sudden liver inflammation may show yellow skin, dark urine, and tiredness.', '急性肝炎可表现为黄疸、深色尿和乏力。', array['viral hepatitis', 'acute hepatitis', 'hepatitis B']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('10687d0d-5172-5fac-b1e5-80133f6e6d8b', 'medical_english:morphology:gastritis:noun:med-morphology-gastritis-001', 'ef08d384-9dea-5dc4-bc09-b306daa4ead1', 'Epigastric pain after heavy drinking suggested acute gastritis.', 'gastritis', 'Pain high in the belly after drinking a lot made stomach-lining inflammation likely.', '大量饮酒后的上腹痛提示急性胃炎。', array['acute gastritis', 'chronic gastritis', 'erosive gastritis']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('b105fa35-d8d5-5a25-bb8d-d7d076ed5d14', 'medical_english:morphology:arthritis:noun:med-morphology-arthritis-001', '0f69a679-de9b-5e73-a2c7-ca13209e4603', 'Morning stiffness in both knees was consistent with inflammatory arthritis.', 'arthritis', 'Both knees felt stiff in the morning in a way that fit joint inflammation.', '双膝晨僵符合炎性关节炎。', array['inflammatory arthritis', 'septic arthritis', 'rheumatoid arthritis']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('2d424e5f-be59-505b-93fe-f7c322c7a371', 'medical_english:morphology:leukemia:noun:med-morphology-leukemia-001', 'f40f9764-b069-5ff3-bf64-4da82e5f22db', 'Unexplained bruising and fatigue prompted testing for leukemia.', 'leukemia', 'Odd bruising and tiredness led doctors to look for a white-cell cancer.', '不明原因瘀斑和乏力促使排查白血病。', array['acute leukemia', 'chronic leukemia', 'diagnose leukemia']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('3f400b66-8cf2-5835-ba1f-c0e15796862b', 'medical_english:morphology:anemia:noun:med-morphology-anemia-001', '00b9b585-bb9a-5859-be85-8a8e53a2d6d8', 'Repeat laboratory tests confirmed iron-deficiency anemia.', 'anemia', 'Blood tests showed too little hemoglobin because the body lacked iron.', '化验证实为缺铁性贫血。', array['iron-deficiency anemia', 'severe anemia', 'anemia of chronic disease']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('7881252f-1427-5364-b0a6-0b86ae36ab39', 'medical_english:morphology:hyperglycemia:noun:med-morphology-hyperglycemia-001', '6aaf515e-ba87-5d97-a171-9311971640f7', 'Morning hyperglycemia persisted despite the overnight insulin adjustment.', 'hyperglycemia', 'Blood sugar was still too high in the morning after the night insulin change.', '尽管夜间胰岛素已调整，晨起高血糖仍持续。', array['fasting hyperglycemia', 'severe hyperglycemia', 'correct hyperglycemia']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('71af95b0-c96d-5b93-8124-24855a136a03', 'medical_english:morphology:hypoglycemia:noun:med-morphology-hypoglycemia-001', 'ac27ae1e-4cb6-52f3-aab7-90b426bdc12f', 'Sweating and confusion resolved after the nurse treated hypoglycemia.', 'hypoglycemia', 'The patient stopped sweating and thinking unclearly after low blood sugar was treated.', '护士处理低血糖后，出汗和意识混乱缓解。', array['symptomatic hypoglycemia', 'treat hypoglycemia', 'recurrent hypoglycemia']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('fdef2e2f-e12f-5ec9-b3c4-5ad2d266000e', 'medical_english:morphology:hypertension:noun:med-morphology-hypertension-001', '0644f027-a925-5f06-8802-e999b066e300', 'Long-standing hypertension was managed with a daily oral agent.', 'hypertension', 'High blood pressure that had lasted for years was treated with a daily pill.', '长期高血压以每日口服药控制。', array['essential hypertension', 'uncontrolled hypertension', 'history of hypertension']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('46b6c756-0097-5b0a-a144-f21d252fb861', 'medical_english:morphology:hypotension:noun:med-morphology-hypotension-001', 'f63a763c-82d6-5d6e-93ec-b05f4f232e54', 'Standing too quickly caused dizziness from postural hypotension.', 'hypotension', 'Getting up fast made the patient dizzy because blood pressure dropped on standing.', '突然站起引起体位性低血压相关头晕。', array['postural hypotension', 'persistent hypotension', 'correct hypotension']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('48b05ec4-1c72-5303-a308-a473f2440aae', 'medical_english:morphology:tachycardia:noun:med-morphology-tachycardia-001', '9938ac2c-db4f-59f9-8fd2-1b29d7815b49', 'Sinus tachycardia accompanied the fever and volume loss.', 'tachycardia', 'The heart beat too fast in a normal rhythm while the patient had fever and lost fluid.', '发热和容量丢失时出现窦性心动过速。', array['sinus tachycardia', 'ventricular tachycardia', 'resting tachycardia']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('f547f69f-00d8-512d-a0f9-d2af69c8e9ff', 'medical_english:morphology:bradycardia:noun:med-morphology-bradycardia-001', '6168fa0d-0b47-5cf7-8099-adc6c5a01da6', 'Overnight telemetry showed intermittent bradycardia to 42 beats per minute.', 'bradycardia', 'Night heart monitoring found periods when the pulse slowed to 42 beats a minute.', '夜间遥测显示间歇性心动过缓，低至每分钟 42 次。', array['sinus bradycardia', 'symptomatic bradycardia', 'nocturnal bradycardia']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('31623e24-5a85-5bf5-93f4-0e80545e5a83', 'medical_english:morphology:neuropathy:noun:med-morphology-neuropathy-001', 'd579e8ca-db94-5e11-aa4e-b9aca4bb9bc0', 'Burning pain in both feet suggested diabetic neuropathy.', 'neuropathy', 'A burning feeling in both feet fit nerve damage from diabetes.', '双足烧灼痛提示糖尿病周围神经病变。', array['diabetic neuropathy', 'peripheral neuropathy', 'sensory neuropathy']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('649a078b-2f44-5ad9-bbd5-53683bb283c0', 'medical_english:morphology:myopathy:noun:med-morphology-myopathy-001', '857a7a18-c3cb-58b9-935b-784bf25279f7', 'Proximal weakness and a high creatine kinase raised concern for drug-induced myopathy.', 'myopathy', 'Weakness close to the trunk plus a high muscle enzyme made a drug-related muscle disease likely.', '近端无力和肌酸激酶升高使医生担心药物性肌病。', array['drug-induced myopathy', 'inflammatory myopathy', 'proximal myopathy']::text[], 'case_report', 'original_example', null, null, null, null),
  ('8ae82f66-e556-59ee-95fc-2e50b6baedfe', 'medical_english:morphology:osteoporosis:noun:med-morphology-osteoporosis-001', 'b7506dc2-0b92-5a0f-bbba-6d2a937e2fea', 'A vertebral compression fracture was attributed to osteoporosis.', 'osteoporosis', 'A crushed spine bone was blamed on bones that had become thin and fragile.', '椎体压缩骨折被归因于骨质疏松。', array['postmenopausal osteoporosis', 'severe osteoporosis', 'osteoporosis-related fracture']::text[], 'imaging_report', 'original_example', null, null, null, null),
  ('d3e0f37a-9a80-5423-967e-182be84c4511', 'medical_english:morphology:hematoma:noun:med-morphology-hematoma-001', '52622478-30c2-5753-bbee-2b74a6a91c46', 'A tender hematoma formed at the injection site.', 'hematoma', 'A sore lump of trapped blood appeared where the shot was given.', '注射部位形成压痛性血肿。', array['subcutaneous hematoma', 'expanding hematoma', 'evacuate a hematoma']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('0c0ff3a1-a2b5-5fda-bc86-73443a2c7c48', 'medical_english:morphology:hemorrhage:noun:med-morphology-hemorrhage-001', '76fd5eb3-dfb4-5875-a98d-fa374c7560fa', 'Gastrointestinal hemorrhage presented as black stools and a falling hemoglobin.', 'hemorrhage', 'Bleeding in the gut showed up as black stool and a dropping blood count.', '消化道出血表现为黑便和血红蛋白下降。', array['gastrointestinal hemorrhage', 'intracranial hemorrhage', 'stop the hemorrhage']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('b7d8a9ee-5b0a-5f2e-850b-1897f1a43bb6', 'medical_english:morphology:intravenous:adjective:med-morphology-intravenous-001', '5d4b1501-1a63-5847-be95-a0029e9d7f14', 'The team started intravenous fluids for dehydration.', 'intravenous', 'Fluid was given through a vein because the patient was dried out.', '因脱水开始静脉补液。', array['intravenous fluids', 'intravenous antibiotics', 'intravenous access']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('5dcba06d-779b-5dc1-a573-c0c364f99aaa', 'medical_english:morphology:subcutaneous:adjective:med-morphology-subcutaneous-001', 'f70995bc-2cd0-53d7-be5c-6c90c96fff52', 'Insulin was given by subcutaneous injection before breakfast.', 'subcutaneous', 'The insulin shot went into the fat just under the skin before breakfast.', '早餐前予皮下注射胰岛素。', array['subcutaneous injection', 'subcutaneous tissue', 'subcutaneous insulin']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('94546c45-984b-5c1e-acba-2b83c6858259', 'medical_english:morphology:neoplasm:noun:med-morphology-neoplasm-001', '11a61f0f-768e-5867-8b03-934390af2c3f', 'Imaging showed a solitary lung neoplasm awaiting biopsy.', 'neoplasm', 'The scan found one new growth in the lung that still needed a tissue sample.', '影像显示孤立性肺部肿瘤，等待活检。', array['benign neoplasm', 'malignant neoplasm', 'solitary neoplasm']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('1b85df8a-9def-5cc8-9097-a8db6b9b5cb0', 'medical_english:morphology:carcinoma:noun:med-morphology-carcinoma-001', 'ed4669d1-326a-5d36-b420-40eccbe82e50', 'Biopsy confirmed squamous cell carcinoma of the lung.', 'carcinoma', 'The tissue sample showed a cancer that started from the lung lining cells.', '活检证实为肺鳞状细胞癌。', array['squamous cell carcinoma', 'basal cell carcinoma', 'in situ carcinoma']::text[], 'case_report', 'original_example', null, null, null, null),
  ('9514e036-af69-5bda-93c5-38748182adeb', 'medical_english:morphology:metastasis:noun:med-morphology-metastasis-001', 'f0dd024b-6c1a-5391-a8db-813b1376450e', 'A liver lesion was consistent with a metastasis from the colon primary.', 'metastasis', 'A spot in the liver looked like colon cancer that had moved there.', '肝内病灶符合结肠原发灶的转移。', array['distant metastasis', 'liver metastasis', 'site of metastasis']::text[], 'imaging_report', 'original_example', null, null, null, null),
  ('82f395b5-3131-5442-ab28-f13efa5988e5', 'medical_english:morphology:biopsy:noun:med-morphology-biopsy-001', '517b0224-26f1-53b7-862b-3a3069b8f96a', 'A skin biopsy was sent to confirm the rash diagnosis.', 'biopsy', 'A small piece of skin was taken so the lab could confirm what the rash was.', '取皮肤活检以明确皮疹诊断。', array['skin biopsy', 'needle biopsy', 'biopsy confirmed']::text[], 'operative_note', 'original_example', null, null, null, null),
  ('26ab8e96-2ee2-5553-a872-982a5544063e', 'medical_english:morphology:prognosis:noun:med-morphology-prognosis-001', '9dcd9f90-cfd5-5a7d-959d-d23f833457c9', 'Early treatment improved the prognosis of community-acquired pneumonia.', 'prognosis', 'Starting treatment early made a better recovery from pneumonia more likely.', '早期治疗改善了社区获得性肺炎的预后。', array['poor prognosis', 'improve the prognosis', 'long-term prognosis']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('276a7345-9fc8-5fd6-a945-38d5190550e9', 'medical_english:morphology:diagnosis:noun:med-morphology-diagnosis-001', '413dc419-b817-588e-8de9-16a356316714', 'The working diagnosis was acute pyelonephritis pending urine culture.', 'diagnosis', 'Doctors currently named the illness as a kidney infection while waiting for the urine test.', '在尿培养回报前，工作诊断为急性肾盂肾炎。', array['working diagnosis', 'final diagnosis', 'confirm the diagnosis']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('ca11bc11-887a-532c-8d46-e39ae699c31a', 'medical_english:morphology:antibiotic:noun:med-morphology-antibiotic-001', '7ce6fedc-390d-5301-b89d-8ee697729495', 'Empiric antibiotic therapy was started after blood cultures were drawn.', 'antibiotic', 'An antimicrobial drug was begun once blood had been taken to grow any germs.', '抽取血培养后开始经验性抗生素治疗。', array['oral antibiotic', 'broad-spectrum antibiotic', 'antibiotic therapy']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('d6999a49-774c-5027-bc76-43574ccf61cd', 'medical_english:morphology:antipyretic:noun:med-morphology-antipyretic-001', '17f49a67-5f61-5573-908e-c9b05cc02e7c', 'An antipyretic was given when the temperature reached 39.2 °C.', 'antipyretic', 'A fever-lowering medicine was given after the temperature rose to 39.2 °C.', '体温达到 39.2 °C 时给予退热药。', array['give an antipyretic', 'oral antipyretic', 'antipyretic effect']::text[], 'medical_record', 'original_example', null, null, null, null)
